\operatorname{BSub}^{x}_{dmCub}(z,E,x,N)=
\begin{cases}
E,&z=x,\\
E[x:=N],&z\ne x\ \wedge\ z\notin\operatorname{FV}_{dmCub}(N),\\
(E[z:=w])[x:=N],&z\ne x\ \wedge\ z\in\operatorname{FV}_{dmCub}(N),
\end{cases}

\operatorname{BSub}^{i}_{dmCub}(j,E,i,r)=
\begin{cases}
E,&j=i,\\
E[i:=r],&j\ne i\ \wedge\ j\notin\operatorname{FDV}_{dm}(r),\\
(E[j:=w])[i:=r],&j\ne i\ \wedge\ j\in\operatorname{FDV}_{dm}(r),
\end{cases}
